'use client';

import { useEffect, useState, useRef } from 'react';
import Layout from '@/components/layout/layout';
import AuthGuard from '@/components/auth/auth-guard';
import {
  DocumentTextIcon,
  ArrowDownTrayIcon,
  FunnelIcon,
  MagnifyingGlassIcon,
  ShoppingBagIcon,
  ArchiveBoxIcon,
  UserGroupIcon,
  CloudArrowDownIcon,
  PlusIcon,
  ArrowPathIcon,
  BuildingOfficeIcon
} from '@heroicons/react/24/outline';
import { formatDate, formatCurrency, formatNumber, getErrorMessage } from '@/lib/utils';
import { api } from '@/lib/api';
import { DashboardSummaryResponse, StockLevelResponse, BranchResponse } from '@/types';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import html2canvas from 'html2canvas';
import { StockReportPDFTemplate } from '@/components/reports/StockReportPDF';
import * as ExcelJS from 'exceljs';
import { saveAs } from 'file-saver';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Card } from '@/components/ui/card';
import { Separator } from '@/components/ui/separator';
import { useToast } from '@/components/ui/toaster';

// Types
interface ReportDefinition {
  id: string;
  name: string;
  description: string;
  type: 'Sales' | 'Inventory';
  endpoint: string;
}

const reportDefinitions: ReportDefinition[] = [
  {
    id: 'inventory-summary',
    name: 'Inventory Summary Report',
    description: 'Complete inventory overview across all branches',
    type: 'Inventory',
    endpoint: '/reports/inventory-summary'
  },
  {
    id: 'low-stock',
    name: 'Low Stock Alert Report',
    description: 'Products below minimum stock thresholds',
    type: 'Inventory',
    endpoint: '/reports/low-stock'
  },
  {
    id: 'stock-movement',
    name: 'Stock Movement Report',
    description: 'Track inventory transfers and adjustments',
    type: 'Inventory',
    endpoint: '/reports/stock-movement'
  },
  {
    id: 'sales-summary',
    name: 'Sales Summary Report',
    description: 'Sales performance across all branches',
    type: 'Sales',
    endpoint: '/reports/sales-summary'
  },
  {
    id: 'top-products',
    name: 'Top Selling Products Report',
    description: 'Best performing products by revenue and quantity',
    type: 'Sales',
    endpoint: '/reports/top-products'
  }
];

export default function AdvancedReportsPage() {
  const { toast } = useToast();
  const [selectedReport, setSelectedReport] = useState<ReportDefinition | null>(null);
  const [reportData, setReportData] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [branches, setBranches] = useState<BranchResponse[]>([]);
  const [selectedBranch, setSelectedBranch] = useState<string>('all');
  const [dateRange, setDateRange] = useState<string>('30days');
  const [reportFormat, setReportFormat] = useState<'pdf' | 'excel'>('pdf');
  const reportRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    fetchBranches();
  }, []);

  const fetchBranches = async () => {
    try {
      const response = await api.branches.getAll();
      if (response.success) {
        setBranches(response.data);
      }
    } catch (err) {
      console.error('Failed to fetch branches:', err);
    }
  };

  const generateReport = async () => {
    if (!selectedReport) return;

    try {
      setLoading(true);
      const response = await api.reports.generate({
        reportId: selectedReport.id,
        branchId: selectedBranch === 'all' ? undefined : selectedBranch,
        dateRange,
        format: 'json'
      });

      if (response.success) {
        setReportData(response.data);
      } else {
        throw new Error(response.message || 'Failed to generate report');
      }
    } catch (err: unknown) {
      const errorMsg = err instanceof Error ? err.message : 'Failed to generate report';
      toast({
        title: 'Error',
        description: errorMsg,
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const downloadReport = async () => {
    if (!selectedReport || !reportData) return;

    try {
      setGenerating(true);
      
      if (reportFormat === 'pdf') {
        await generatePDF();
      } else {
        await generateExcel();
      }
      
      toast({
        title: 'Success',
        description: `${selectedReport.name} downloaded successfully`,
      });
    } catch (err: unknown) {
      const errorMsg = err instanceof Error ? err.message : 'Failed to download report';
      toast({
        title: 'Error',
        description: errorMsg,
        variant: 'destructive',
      });
    } finally {
      setGenerating(false);
    }
  };

  const generatePDF = async () => {
    const pdf = new jsPDF();
    
    // Add title
    pdf.setFontSize(20);
    pdf.text(selectedReport!.name, 20, 20);
    
    pdf.setFontSize(12);
    pdf.text(`Generated: ${formatDate(new Date())}`, 20, 30);
    
    if (selectedBranch !== 'all') {
      const branch = branches.find(b => b.id === selectedBranch);
      pdf.text(`Branch: ${branch?.name || 'Unknown'}`, 20, 40);
    }
    
    pdf.text(`Date Range: ${dateRange}`, 20, 50);

    // Add content based on report type
    if (selectedReport?.type === 'Inventory' && reportData) {
      // Inventory report table
      const tableData = reportData.map((item: any) => [
        item.productName || '',
        item.productSku || '',
        item.branchName || '',
        item.quantityOnHand || 0,
        item.minimumStockThreshold || 0,
        formatCurrency(item.costPrice || 0),
        formatCurrency(item.sellingPrice || 0)
      ]);
      
      autoTable(pdf, {
        head: [['Product', 'SKU', 'Branch', 'Quantity', 'Min Stock', 'Cost Price', 'Selling Price']],
        body: tableData,
        startY: 60,
      });
    } else if (selectedReport?.type === 'Sales' && reportData) {
      // Sales report table
      const tableData = reportData.map((item: any) => [
        item.productName || '',
        item.totalQuantitySold || 0,
        formatCurrency(item.totalRevenue || 0),
        formatDate(item.date) || ''
      ]);
      
      autoTable(pdf, {
        head: [['Product', 'Quantity Sold', 'Revenue', 'Date']],
        body: tableData,
        startY: 60,
      });
    }

    // Save PDF
    pdf.save(`${selectedReport!.name.replace(/\s+/g, '_').toLowerCase()}.pdf`);
  };

  const generateExcel = async () => {
    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet(selectedReport!.name);

    // Add headers
    if (selectedReport?.type === 'Inventory') {
      worksheet.columns = [
        { header: 'Product Name', key: 'productName', width: 30 },
        { header: 'SKU', key: 'productSku', width: 15 },
        { header: 'Branch', key: 'branchName', width: 20 },
        { header: 'Quantity', key: 'quantityOnHand', width: 12 },
        { header: 'Min Stock', key: 'minimumStockThreshold', width: 12 },
        { header: 'Cost Price', key: 'costPrice', width: 15 },
        { header: 'Selling Price', key: 'sellingPrice', width: 15 },
      ];
    } else if (selectedReport?.type === 'Sales') {
      worksheet.columns = [
        { header: 'Product Name', key: 'productName', width: 30 },
        { header: 'Quantity Sold', key: 'totalQuantitySold', width: 15 },
        { header: 'Revenue', key: 'totalRevenue', width: 15 },
        { header: 'Date', key: 'date', width: 15 },
      ];
    }

    // Add data
    worksheet.addRows(reportData);

    // Style the header row
    const headerRow = worksheet.getRow(1);
    headerRow.font = { bold: true };
    headerRow.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: 'FFE0E0E0' }
    };

    // Generate buffer and save
    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    saveAs(blob, `${selectedReport!.name.replace(/\s+/g, '_').toLowerCase()}.xlsx`);
  };

  return (
    <AuthGuard>
      <Layout>
        <div className="space-y-6">
          {/* Header */}
          <div>
            <h1 className="text-2xl font-bold text-primary">Advanced Reports</h1>
            <p className="mt-1 text-sm text-text-secondary">
              Generate detailed reports with custom filters and export options
            </p>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Report Selection */}
            <Card className="lg:col-span-1 p-6">
              <h2 className="text-lg font-bold text-primary mb-4">Select Report</h2>
              
              <div className="space-y-3">
                {reportDefinitions.map((report) => (
                  <button
                    key={report.id}
                    onClick={() => setSelectedReport(report)}
                    className={`w-full text-left p-4 rounded-xl border transition-all duration-200 ${
                      selectedReport?.id === report.id
                        ? 'border-primary bg-primary/5 text-primary'
                        : 'border-divider hover:border-primary/50 hover:bg-surface'
                    }`}
                  >
                    <div className="flex items-start gap-3">
                      <div className={`p-2 rounded-lg ${
                        report.type === 'Inventory' ? 'bg-info/10' : 'bg-success/10'
                      }`}>
                        {report.type === 'Inventory' ? (
                          <ArchiveBoxIcon className="h-5 w-5 text-info" />
                        ) : (
                          <ShoppingBagIcon className="h-5 w-5 text-success" />
                        )}
                      </div>
                      <div className="flex-1">
                        <h3 className="font-bold text-sm">{report.name}</h3>
                        <p className="text-xs text-text-secondary mt-1">{report.description}</p>
                        <Badge variant="outline" className="mt-2 text-xs">
                          {report.type}
                        </Badge>
                      </div>
                    </div>
                  </button>
                ))}
              </div>
            </Card>

            {/* Report Configuration and Preview */}
            <Card className="lg:col-span-2 p-6">
              {selectedReport ? (
                <div className="space-y-6">
                  {/* Configuration */}
                  <div>
                    <h2 className="text-lg font-bold text-primary mb-4">Report Configuration</h2>
                    
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                      <div>
                        <label className="block text-sm font-medium text-text-secondary mb-2">Branch</label>
                        <Select value={selectedBranch} onValueChange={setSelectedBranch}>
                          <SelectTrigger>
                            <SelectValue placeholder="Select branch" />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="all">All Branches</SelectItem>
                            {branches.map((branch) => (
                              <SelectItem key={branch.id} value={branch.id}>
                                {branch.name}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>

                      <div>
                        <label className="block text-sm font-medium text-text-secondary mb-2">Date Range</label>
                        <Select value={dateRange} onValueChange={setDateRange}>
                          <SelectTrigger>
                            <SelectValue placeholder="Select date range" />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="7days">Last 7 Days</SelectItem>
                            <SelectItem value="30days">Last 30 Days</SelectItem>
                            <SelectItem value="90days">Last 90 Days</SelectItem>
                            <SelectItem value="1year">Last Year</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>

                      <div>
                        <label className="block text-sm font-medium text-text-secondary mb-2">Format</label>
                        <Select value={reportFormat} onValueChange={(value: 'pdf' | 'excel') => setReportFormat(value)}>
                          <SelectTrigger>
                            <SelectValue placeholder="Select format" />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="pdf">PDF</SelectItem>
                            <SelectItem value="excel">Excel</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>
                    </div>

                    <div className="flex gap-3 mt-6">
                      <Button 
                        onClick={generateReport} 
                        disabled={loading}
                        className="flex-1"
                      >
                        {loading ? (
                          <>
                            <ArrowPathIcon className="h-4 w-4 mr-2 animate-spin" />
                            Generating...
                          </>
                        ) : (
                          <>
                            <FunnelIcon className="h-4 w-4 mr-2" />
                            Generate Report
                          </>
                        )}
                      </Button>
                      
                      {reportData && (
                        <Button 
                          onClick={downloadReport} 
                          disabled={generating}
                          variant="outline"
                        >
                          {generating ? (
                            <>
                              <ArrowPathIcon className="h-4 w-4 mr-2 animate-spin" />
                              Processing...
                            </>
                          ) : (
                            <>
                              <ArrowDownTrayIcon className="h-4 w-4 mr-2" />
                              Download
                            </>
                          )}
                        </Button>
                      )}
                    </div>
                  </div>

                  <Separator />

                  {/* Report Preview */}
                  <div ref={reportRef}>
                    <h2 className="text-lg font-bold text-primary mb-4">Report Preview</h2>
                    
                    {loading ? (
                      <div className="text-center py-12 text-text-secondary">
                        <ArrowPathIcon className="h-8 w-8 mx-auto mb-4 animate-spin" />
                        <p>Generating report...</p>
                      </div>
                    ) : reportData ? (
                      <div className="border border-divider rounded-xl overflow-hidden">
                        <div className="p-4 bg-surface border-b border-divider">
                          <h3 className="font-bold text-primary">{selectedReport.name}</h3>
                          <p className="text-sm text-text-secondary">
                            Generated: {formatDate(new Date())}
                            {selectedBranch !== 'all' && ` • ${branches.find(b => b.id === selectedBranch)?.name}`}
                            {' • '}{dateRange}
                          </p>
                        </div>
                        
                        <div className="overflow-x-auto">
                          <table className="w-full">
                            <thead className="bg-surface">
                              <tr>
                                {selectedReport.type === 'Inventory' && (
                                  <>
                                    <th className="text-left p-3 text-xs font-black text-text-secondary uppercase">Product</th>
                                    <th className="text-left p-3 text-xs font-black text-text-secondary uppercase">SKU</th>
                                    <th className="text-left p-3 text-xs font-black text-text-secondary uppercase">Branch</th>
                                    <th className="text-right p-3 text-xs font-black text-text-secondary uppercase">Quantity</th>
                                    <th className="text-right p-3 text-xs font-black text-text-secondary uppercase">Min Stock</th>
                                    <th className="text-right p-3 text-xs font-black text-text-secondary uppercase">Cost Price</th>
                                    <th className="text-right p-3 text-xs font-black text-text-secondary uppercase">Selling Price</th>
                                  </>
                                )}
                                {selectedReport.type === 'Sales' && (
                                  <>
                                    <th className="text-left p-3 text-xs font-black text-text-secondary uppercase">Product</th>
                                    <th className="text-right p-3 text-xs font-black text-text-secondary uppercase">Quantity Sold</th>
                                    <th className="text-right p-3 text-xs font-black text-text-secondary uppercase">Revenue</th>
                                    <th className="text-left p-3 text-xs font-black text-text-secondary uppercase">Date</th>
                                  </>
                                )}
                              </tr>
                            </thead>
                            <tbody className="divide-y divide-divider">
                              {reportData.slice(0, 10).map((item: any, index: number) => (
                                <tr key={index} className="hover:bg-surface/50">
                                  {selectedReport.type === 'Inventory' && (
                                    <>
                                      <td className="p-3 text-sm">{item.productName || '-'}</td>
                                      <td className="p-3 text-sm font-mono">{item.productSku || '-'}</td>
                                      <td className="p-3 text-sm">{item.branchName || '-'}</td>
                                      <td className="p-3 text-sm text-right">{item.quantityOnHand || 0}</td>
                                      <td className="p-3 text-sm text-right">{item.minimumStockThreshold || 0}</td>
                                      <td className="p-3 text-sm text-right">{formatCurrency(item.costPrice || 0)}</td>
                                      <td className="p-3 text-sm text-right">{formatCurrency(item.sellingPrice || 0)}</td>
                                    </>
                                  )}
                                  {selectedReport.type === 'Sales' && (
                                    <>
                                      <td className="p-3 text-sm">{item.productName || '-'}</td>
                                      <td className="p-3 text-sm text-right">{item.totalQuantitySold || 0}</td>
                                      <td className="p-3 text-sm text-right font-bold">{formatCurrency(item.totalRevenue || 0)}</td>
                                      <td className="p-3 text-sm">{formatDate(item.date) || '-'}</td>
                                    </>
                                  )}
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        </div>
                        
                        {reportData.length > 10 && (
                          <div className="p-4 bg-surface border-t border-divider text-center text-sm text-text-secondary">
                            Showing 10 of {reportData.length} records. Download the full report to see all data.
                          </div>
                        )}
                      </div>
                    ) : (
                      <div className="text-center py-12 text-text-secondary border border-divider rounded-xl">
                        <DocumentTextIcon className="h-12 w-12 mx-auto mb-4 opacity-20" />
                        <p className="font-bold">No data to display</p>
                        <p className="text-sm opacity-60">Generate a report to see the preview</p>
                      </div>
                    )}
                  </div>
                </div>
              ) : (
                <div className="text-center py-12 text-text-secondary">
                  <DocumentTextIcon className="h-12 w-12 mx-auto mb-4 opacity-20" />
                  <p className="font-bold">Select a report type</p>
                  <p className="text-sm opacity-60">Choose a report from the left panel to get started</p>
                </div>
              )}
            </Card>
          </div>
        </div>
      </Layout>
    </AuthGuard>
  );
}
